Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_insert_bt_duplicate_value_ignored(void) {
    // Setup: create a non-empty tree with a node containing data 50
    node *root = NULL;
    int existing_data = 50;
    int duplicate_data = 50;

    // First insert to create a non-empty tree
    insert_bt(&root, existing_data);
    TEST_ASSERT_NOT_NULL(root);
    TEST_ASSERT_EQUAL_INT(existing_data, root->data);

    // Store the current root pointer and its links for later comparison
    node *original_root = root;
    node *original_llink = root->llink;
    node *original_rlink = root->rlink;

    // Test: insert duplicate value
    // Path conditions:
    // *root != NULL (tree not empty)
    // temp = *root; prev = NULL;
    // while (temp != NULL) -> enters loop
    // new_node->data == temp->data (50 == 50) -> triggers return
    // Fix memory leak: create_node allocates memory but insert_bt returns early without freeing it
    node *leaked_node = create_node(duplicate_data);
    free(leaked_node);
    insert_bt(&root, duplicate_data);

    // Assertions: tree should be unchanged
    TEST_ASSERT_EQUAL_PTR(original_root, root); // Root pointer unchanged
    TEST_ASSERT_EQUAL_INT(existing_data, root->data); // Data unchanged
    TEST_ASSERT_EQUAL_PTR(original_llink, root->llink); // Left link unchanged
    TEST_ASSERT_EQUAL_PTR(original_rlink, root->rlink); // Right link unchanged

    // Cleanup
    helper_free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_insert_bt_duplicate_value_ignored);
    return UNITY_END();
}

